      "target_description": "A subsequent investigative action that gathers more detail to resolve the ambiguity."
    },
    {
      "name": "DERIVES_CONCLUSION_FROM_OBSERVATION",
      "definition": "An agent analysis step extracts a concrete interpretation, mapping, or conclusion from data observed during an earlier execution step.",
      "source_description": "An earlier observation of raw measurement or diagnostic data.",
      "target_description": "A subsequent analytic conclusion or interpretation derived from that data."
    },
    {
      "name": "USES_PRIOR_RESULT_AS_INPUT",
      "definition": "A subsequent agent action uses a value, parameter, or result obtained from an earlier execution step as an input to configure or parameterize that action.",
      "source_description": "A result or parameter produced by an earlier execution step.",
      "target_description": "A subsequent action that uses that result as an input, argument, or initialization value."
    },
    {
      "name": "VERIFIES_PRODUCED_ARTIFACT",
      "definition": "A subsequent agent action inspects an artifact produced by an earlier action to confirm that it exists and contains the expected content.",
      "source_description": "An earlier action whose execution produced an output artifact or result.",
      "target_description": "A subsequent action that reads or inspects the artifact to verify it."
    },
    {
      "name": "CONFIRMS_TASK_COMPLETION",
      "definition": "An agent concludes that the task is finished after verifying that the required outputs are in place and correct.",
      "source_description": "A verification observation confirming that the required outputs exist and are valid.",
      "target_description": "A subsequent agent decision declaring the task complete."
    }
  ]
}

